-- 20260822000007_corpus_findings.sql
--
-- Coach's research corpus (owner "punch it" 2026-08-22): the swarms'
-- distilled findings (396 entries - structured pass findings +
-- synthesis-doc paragraphs) become the on-device CorpusResearchTool's
-- lookup, and corpus_misses is the demand queue: questions the corpus
-- couldn't answer, swept periodically into new deep-read passes.
CREATE TABLE public.corpus_findings (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  area       text NOT NULL,
  topic      text NOT NULL DEFAULT '',
  claim      text NOT NULL,
  basis      text NOT NULL DEFAULT '',
  confidence text NOT NULL DEFAULT '',
  sport      text,
  quantities jsonb
);
ALTER TABLE public.corpus_findings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "findings globally readable"
  ON public.corpus_findings FOR SELECT TO authenticated USING (true);

CREATE TABLE public.corpus_misses (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  question   text NOT NULL,
  status     text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'researched', 'dismissed')),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.corpus_misses ENABLE ROW LEVEL SECURITY;
-- Insert-only for clients (the queue is dev-facing; reads via service).
CREATE POLICY "log own misses"
  ON public.corpus_misses FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid());

