INSERT INTO public.corpus_findings (area, topic, claim, basis, confidence, sport, quantities) VALUES
  ('smith', 'hypertrophy', 'Smith squats bias effort toward the concentric portion and reduce eccentric loading, which the speaker argues may blunt hypertrophy since eccentric-emphasized loading is thought to drive slightly more growth.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'hypertrophy', 'Free barbell squats keep concentric and eccentric force essentially equal, avoiding the machine-friction-driven force asymmetry that may make Smith squats slightly less effective for growth.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'hypertrophy', 'Despite the concentric/eccentric imbalance, Smith machine squats can still robustly build quad, glute, and adductor size, just with somewhat less lower-back stimulus than free squats.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'strength', 'Free squats transfer better to sport and real-world strength because their balance demand builds force-production-under-instability that Smith machine training doesn''t teach, though the gap is small.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'The fixed Smith rail removes the balance task, letting lifters focus entirely on foot and torso positioning to maximize quad mind-muscle connection during squats.', 'experience', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'Smith squats are useful variation for intermediate/advanced lifters and permit stances, like a very close foot placement, that would cause a lifter to fall over in a free squat.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Because the rail fixes the bar path, placing feet too far forward or back causes excessive knee strain or butt-wink/lower-back stress, errors a free squat''s balance requirement would prevent.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Without deeply ingrained technique (chest leading the ascent, not the hips), lifters can good-morning the Smith squat weight up while barely using quads; beginners should avoid it.', 'experience', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'Speaker frames the Smith machine as a practical fallback for high-volume arm/shoulder pump work when free-weight equipment or spotters are unavailable, since a lifter can rerack solo quickly.', 'experience', 'strong', NULL, NULL),
  ('smith', 'exercises', 'Smith machine overhead press felt less stressful on the shoulders than a free barbell press while emphasizing front-delt and upper-pec pump.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": "7-9"}'::jsonb),
  ('smith', 'exercises', 'Leaning back into the fixed Smith bar during upright rows shifted emphasis toward medial delts and traps with less shoulder discomfort than a free-standing barbell upright row.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'exercises', 'A one-arm row set up on the Smith rail let the lifter load heavier and adjust torso angle to bias traps/rhomboids versus lats depending on stance.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": "17 per arm"}'::jsonb),
  ('smith', 'exercises', 'Chest-supported rows on the Smith machine isolated lats and rear delts by removing the lower-back and hamstring involvement typical of free bent-over rows.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": "20-25"}'::jsonb),
  ('smith', 'use_cases', 'Smith machine bench pressing isolates the pecs more than free barbell bench pressing because the fixed rail removes stabilizer demand.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'exercises', 'Bench throws performed on the Smith rail trained explosive triceps lockout more safely than free-weight bench throws, since the bar returns on a fixed, predictable path.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'Speaker recommends switching a leg session to the Smith machine when lower-back pain flares up during warm-ups, since the fixed rail reduces spinal stabilization demand versus a free-bar squat.', 'experience', 'strong', NULL, NULL),
  ('smith', 'exercises', 'Smith machine curtsy lunges, with the front foot fixed and back leg crossed behind, let lifters load the glute medius heavier than a dumbbell goblet version allows.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": "7 per leg"}'::jsonb),
  ('smith', 'exercises', 'Positioning feet ahead of the rail during a Smith squat keeps hips forward and increases quad loading and stretch versus a standard free-squat stance.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": 20}'::jsonb),
  ('smith', 'exercises', 'Split squats balanced under the Smith bar target the groin and hamstrings in a pattern useful for weightlifters rehearsing a split-jerk receiving position.', 'experience', 'moderate', NULL, '{"sets": 4, "reps": "5 per leg"}'::jsonb),
  ('smith', 'exercises', 'A shortened, top-range squat-to-bench movement on the Smith machine adds extra quad-focused volume with less posterior-chain loading than a full squat.', 'experience', 'moderate', NULL, '{"sets": 5, "reps": "20-25"}'::jsonb),
  ('smith', 'exercises', 'Smith machine front squats prevent the forward lean that shifts load from quads to hamstrings/lower back for long-limbed lifters doing free front squats, though they cap usable weight.', 'experience', 'moderate', NULL, '{"sets": 4, "reps": 7}'::jsonb),
  ('smith', 'hypertrophy', 'Removing upper-back fatigue as a limiter lets lifters push higher front-squat volume on the Smith machine before form breaks down, potentially increasing quad growth stimulus.', 'mechanistic', 'hedged', NULL, NULL),
  ('smith', 'use_cases', 'Foot position on the Smith rail can be shifted deliberately within the same squat pattern to bias quads, hamstrings, or glutes as needed.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Smith machines are widely believed safer than free weights but are actually more dangerous for pressing, since a pinned lifter cannot dump or slide free the way they can with an unclipped barbell.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'The fixed rail lets a lifter squat far off their natural center of gravity (e.g., feet too far forward), producing knee or lower-back strain a free squat''s balance requirement would prevent.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Speaker was pinned under a Smith machine as a teenager and took about 30 seconds to escape, illustrating real entrapment risk.', 'experience', 'strong', NULL, '{"escape_time_sec": 30}'::jsonb),
  ('smith', 'use_cases', 'Safe Smith machine use requires marking or memorizing consistent foot placement every session (e.g., via floor-tile lines or a home chalk mark) to avoid off-center loading.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'A spotter is recommended for Smith machine work even more than for free-bar work, since escaping a failed Smith rep is harder than escaping a failed free-bar rep.', 'experience', 'strong', NULL, NULL),
  ('smith', 'hypertrophy', 'Machine friction (especially on older/rustier units) can reduce the eccentric load below the concentric load, potentially delivering less eccentric-driven growth stimulus than free weights for a matched rep scheme.', 'mechanistic', 'hedged', NULL, NULL),
  ('smith', 'strength', 'Because Smith machine removes the need for postural/stabilizer control, it legitimately transfers less to real-world or athletic strength than free-weight training does.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Because the fixed bar path won''t let hips or knees shift to relieve stress like a free squat does, wrong foot placement on a Smith squat can force damaging positions unnoticed.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Joint strain caused by poor Smith positioning tends to build up gradually rather than causing an obvious acute injury, so lifters can be doing damage for weeks before noticing pain.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'The fixed vertical bar path lets one Smith machine substitute for many free-weight lifts (rows, deadlifts, presses, pull-ups, skull crushers, upright rows), making it valuable purely for exercise variety/versatility.', 'experience', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'Using a Smith machine well requires the lifter to actively adjust body position (e.g., sliding along the bench), since only the lifter''s own body, not the bar, can correct a bad position.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'The Smith machine handles much of the balance/tracking work for the lifter, which makes it a poor tool for teaching beginners fundamental free-weight movement patterns like squats or bench press.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Because the bar cannot naturally shift backward/forward as some exercises (e.g. upright rows) require, using the Smith incorrectly can grind and shear joints, causing chronic wear-and-tear injury over time.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Since new lifters typically don''t know correct positioning, the Smith machine is best kept away from true beginners and treated as a tool for more experienced trainees.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'hypertrophy', 'Contrary to its reputation, the Smith machine is a legitimately effective hypertrophy tool: added external stability can improve mind-muscle connection and let lifters isolate a target muscle better than free weights in some contexts.', 'experience', 'strong', NULL, NULL),
  ('smith', 'hypertrophy', 'Smith machine squats performed with a more forward foot position let lifters stay more upright, shifting emphasis toward the quads and away from the lower back, useful as a training variation.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'strength', 'Strength and conditioning coaches are right to discourage Smith machine use for athletes, since it has little carryover to sports requiring free, unconstrained movement.', 'experience', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'The Smith machine is well suited to dedicated bodybuilding/hypertrophy goals but not to athletic performance training, so its value depends heavily on the trainee''s goal.', 'experience', 'strong', NULL, NULL),
  ('smith', 'exercises', 'The Smith machine overhead press mainly trains the triceps, upper chest, and front delts, providing little direct side-delt stimulus, so it should be paired with a dedicated lateral raise, face pull, or upright row.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'exercises', 'For Smith machine overhead press, keeping the bar close to the face throughout the rep, versus letting it drift forward, increases force output and is less stressful on the shoulders.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'hypertrophy', 'Smith machine squats performed for a taxing rep scheme are highly effective for building leg mass and should be placed early in a leg session, before fatigue sets in.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'Performing Bulgarian split squats on a Smith machine removes the balance/setup difficulty of the free-weight version, letting the lifter apply more intent and output toward the target muscles.', 'experience', 'strong', NULL, NULL),
  ('smith', 'exercises', 'Smith machine split squats also give the rear leg meaningful rectus femoris (quad) work via hip flexion, unlike a standard bilateral squat where that muscle is barely engaged.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'The speaker prefers standing calf raise variations, including on a Smith machine, over hip-flexed leg-press-style calf raises, because the flexed-hip position produces uncomfortable nerve tension behind the knee for him.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'Smith machine overhead/military press is used as a secondary pressing movement specifically for its stability benefit, allowing focused work on a lagging muscle (anterior delts) without extra stabilization demand.', 'experience', 'strong', NULL, NULL),
  ('smith', 'exercises', 'Incline Smith machine bench is favored for combining machine stability with a length-biased resistance curve (harder in the stretched position) similar to free weights, unlike machines that get harder near lockout.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'exercises', 'Recommends the Smith squat, with feet shifted forward, as a deliberate quad-hypertrophy tool distinct from a free-squat substitute, functioning like a hybrid between a hack squat and a free squat.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'Advises positioning feet three to six inches ahead of a normal squat stance so the torso stays upright, heels stay planted, and quads get a strong stretch at depth.', 'mechanistic', 'strong', NULL, '{"foot_shift_inches": "3-6"}'::jsonb),
  ('smith', 'use_cases', 'Says stance width should be individualized rather than fixed; pick whichever width maximizes felt quad tension and stability, since optimal width varies by lifter anatomy.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Warns that too narrow a stance sacrifices stability and force production, risking joint discomfort and an inability to reach full depth with good positioning.', 'mechanistic', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Warns that feet placed too far forward cause a loss of traction and visible lower-back rounding at the bottom of the rep.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'hypertrophy', 'Argues squatting to full depth, near maximal quad stretch, drives the most growth, and depth should only be reduced once the lower back begins rounding.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Warns against shifting into a hip-driven good-morning pattern on the ascent to move more weight, since it shifts load off the quads and defeats the exercise''s purpose.', 'mechanistic', 'strong', NULL, NULL),
  ('smith', 'use_cases', 'Recommends roughly 10-15 reps as the ideal range for Smith squats, with 5-10 usually reserved for free squats and 15-20+ workable but harder to control.', 'experience', 'moderate', NULL, '{"rep_range_primary": "10-15", "rep_range_alt": "5-10, 15-20+"}'::jsonb),
  ('smith', 'use_cases', 'Jeff describes switching his long-standing behind-the-neck press from a barbell to a Smith machine after shoulder and elbow issues on free-weight pressing, eventually training pain-free.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'use_cases', 'Programs the Smith behind-the-neck press for higher reps, rarely below 8 and often 15-20, reasoning heavy low-rep overhead pressing on small shoulder musculature raises injury risk.', 'experience', 'moderate', NULL, '{"rep_range": "8+", "typical_range": "15-20"}'::jsonb),
  ('smith', 'exercises', 'Uses a Smith machine hack squat, feet stepped forward and torso upright, as a home-gym substitute for a dedicated hack squat machine.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Deliberately stays on his midfoot rather than driving through his heels on the Smith hack squat, because heel drive there transfers heavy load onto his lower back.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Accepts extra knee loading from his midfoot Smith hack squat technique, managing it by leaving several reps in reserve and pre-fatiguing quads with leg extensions first.', 'experience', 'moderate', NULL, '{"reps_in_reserve": "3-4"}'::jsonb),
  ('smith', 'use_cases', 'Used a Smith machine pin press limited to roughly the top third of the range of motion to keep training chest through a pectoral tear.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Argues Smith-assisted exercises like the behind-the-neck press get an unearned bad reputation, since bodies adapt resilience to a practiced movement pattern over years.', 'experience', 'hedged', NULL, NULL),
  ('smith', 'strength', 'After years training legs mainly via Smith hack squat, leg press, and leg extensions, found underlying quad strength intact when returning to free squats; only squat skill had eroded.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Argues a Smith machine is a poor home-gym purchase for someone who already owns a barbell, since it mostly duplicates barbell movements and can''t take different attachments.', 'experience', 'strong', NULL, NULL),
  ('smith', 'cautions', 'Notes Smith machines often need more upkeep than a plain barbell, such as greasing and rebalancing, despite performing a similar function.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'cautions', 'Describes a recurring problem where a Smith machine''s carriage becomes unbalanced and binds unevenly to one side, causing a sudden, confusing loss of usable pressing strength.', 'experience', 'strong', NULL, '{"perceived_strength_loss_lb": 80}'::jsonb),
  ('smith', 'use_cases', 'States personal fondness for training on Smith machines generally, distinct from his recommendation against prioritizing one as a home-gym purchase.', 'experience', 'moderate', NULL, NULL),
  ('smith', 'hypertrophy', 'Cites Akagi et al. (18 trained men): Smith machine bench press 1RM correlated with pectoralis major cross-sectional area, though only correlational, not proof training causes growth.', 'cited_study', 'moderate', NULL, '{"n": 18}'::jsonb),
  ('smith', 'hypertrophy', 'Cites Chavez et al. (47 untrained men, 8 weeks, once weekly): flat vs 44-degree incline Smith bench press produced similar sternal/costal growth, but incline produced greater clavicular growth.', 'cited_study', 'strong', NULL, '{"n": 47, "duration_weeks": 8, "sessions_per_week": 1, "rep_range": "8-12"}'::jsonb),
  ('smith', 'exercises', 'Cautions that since the cited incline-vs-flat study used a Smith machine, not a free barbell, results may only partly generalize to free-barbell incline bench pressing.', 'mechanistic', 'hedged', NULL, NULL),
  ('sport-baseball', 'selection', 'Pitchers should build a base of strength and power (force production) before prioritizing throwing mechanics or velocity work; skipping this order is described as the main cause of training plateaus.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'power', 'Strength/power testing (force production and rate of force development) identifies weaknesses that are trained first, since attempting velocity gains without adequate force capacity risks stalled progress and injury.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Recovery quality (roughly 8 to 10 hours of sleep plus adequate nutrition) must be dialed in before advancing to high-intensity velocity work, since poor recovery execution is a common cause of plateaus.', 'experience', 'strong', 'baseball', '{"sleep_hours": "8-10"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Strengthening throwing-specific anatomy (shoulder, forearm, elbow) is framed as necessary both to prevent injury and to improve the athlete''s capacity to absorb and produce force needed for velocity.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Biomechanical assessment and mechanics refinement are placed after strength, power, and recovery in the development sequence, since mechanics work is commonly mis-prioritized too early by athletes.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Injury risk in high-velocity throwing can never be fully eliminated; the same velocity gain carries lower risk when achieved alongside disciplined sleep, nutrition, and recovery practices versus without them.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'A quality off-season throwing program starts with an on-ramp phase that gradually builds toward max-effort throwing, preparing the body for high-intensity work rather than jumping straight into it.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'Driveline''s velocity phase, the high-intensity throwing block following on-ramping, runs about 6 weeks and depends heavily on properly executed low-intensity recovery days between high-effort throwing days to avoid plateaus.', 'experience', 'strong', 'baseball', '{"velocity_phase_weeks": 6}'::jsonb),
  ('sport-baseball', 'power', 'Within a throwing program, explosive max-intent velocity days (plyo throws, pulldowns, weighted-ball, mound work at 100% effort) are interspersed with medium-intensity hybrid days and light recovery days rather than run back-to-back.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'A throwing program should close with a competition phase (pitch design, command work, live at-bats) to translate velocity gains into game performance; velocity gains without this phase are considered wasted.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Strength programming for throwers should prioritize general athleticism via compound lifts (squat, deadlift, bench) plus sprinting/plyometrics for power, deliberately avoiding sport-specific movement mimicry in the weight room.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Athletes should follow one throwing program exclusively rather than mixing programs, since combining programs is said to reduce effectiveness and increase risk of overtraining and confusion.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'In-season weight-room volume reduction scales with training age: highly adapted athletes (e.g., MLB veterans) can cut volume more, near their ceiling, while younger, less-trained players keep training harder.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'selection', 'In-season lifting should target qualities missing from game play, reverse-engineered from sprint, plyometric, and rotational-speed exposure, typically emphasizing absolute strength and power at lower volume instead.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Position-specific gaps guide exercise selection: catchers need less deep-squat volume (already loaded from catching), corner infielders can absorb more plyometric work, and outfielders/pitchers need little added sprint or rotational-speed work.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'conditioning', 'For position players with heavy in-game sprint/conditioning exposure, in-season programming should minimize additional sprint-type conditioning and redirect training time toward absolute strength and power instead.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'In-season lift timing should be waved to match high-stress lifting days with high-stress game days, creating peaks and recovery troughs; a flat, constantly-stressed schedule is said to prevent full recovery and adaptation.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'Starting pitchers on a 5-6 day rotation can program proactively: the heaviest lift right after a start, a volume/tissue-focused lift a few days later, and brief low-volume power/speed work 2-3 days before the next start.', 'experience', 'strong', 'baseball', '{"rotation_days": "5-6"}'::jsonb),
  ('sport-baseball', 'seasons', 'Position players and relief pitchers need reactive rather than proactive in-season lift scheduling, since their playing time and workload vary unpredictably game to game, unlike starting pitchers on a fixed rotation.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'power', 'Speed and power qualities are said to detrain fastest in-season, while absolute strength and aerobic capacity/tissue quality persist longer, so in-season maintenance work should prioritize preserving speed and power.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Arm-care strengthening work does not need to happen immediately post-throwing; it can be distributed across the week (non-throwing days, end of lifts) as long as volume is not excessive right after a high-pitch-count outing.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'The ratio of external-to-internal rotation strength in the posterior rotator cuff is described as a major predictor of future shoulder injury, especially as throwing velocity increases cuff demand.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Lower trapezius training for scapular posterior tilt is needed alongside ball-and-socket external rotation work; without it, pitchers are said to risk impingement, labral, or rotator-cuff tendon issues during layback.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Scapular stabilizers should be trained with isometric co-contraction and perturbation tools (shoulder tube/sphere, waiter walks) in sport-specific positions near 90 degrees, not just isolated-muscle exercises, to build coordinated firing and timing.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'High time-under-tension volume on tools like the shoulder sphere (an example routine used about 9 minutes) is flagged as excessive; the speaker recommends caution against very high volume with that specific tool.', 'experience', 'hedged', 'baseball', '{"shoulder_sphere_example_minutes": 9}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Serratus anterior training should progress beyond simple activation drills (wall slides) into strength/endurance work (scap push-ups, bear crawls) to prevent scapular winging and downward-rotation-related impingement.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Isometric forearm and wrist training across six motions (flexion, extension, radial/ulnar deviation, pronation, supination) is recommended for elbow health, matching the brief isometric grip force applied near ball release.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Wearable strength-sensor comparisons of pre- vs post-throwing rotation strength can flag excessive fatigue; a roughly 15% strength drop is cited as an example red flag warranting reduced volume or a deload.', 'experience', 'hedged', 'baseball', '{"strength_drop_pct_example": 15}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Flexor pronator mass and FCU are the top UCL-protection priority; when these fatigue or weaken, UCL injury risk rises sharply because they normally offload the elbow''s valgus torque during throwing.', 'mechanistic', 'strong', 'baseball', '{"ucl_failure_torque_nm": 35, "peak_elbow_torque_nm": 100}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Fingertip/thumbless farmer''s-walk holds strengthen finger flexors for UCL protection; benchmark target is a 90 lb hold for 60 seconds.', 'experience', 'moderate', 'baseball', '{"load_lb": 90, "duration_sec": 60}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Offset barbell side holds train wrist-deviation (FCU) control to protect the UCL; benchmark is a 60-second hold with 2.5 lb loaded on one end of the bar.', 'experience', 'moderate', 'baseball', '{"load_lb": 2.5, "duration_sec": 60}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Subscapularis strength (eccentric control into external rotation) is an underemphasized arm-care priority, preventing anterior shoulder migration, impingement, and biceps-tendon or labral irritation during layback.', 'mechanistic', 'strong', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Scapular stabilizers (serratus anterior, lower/mid trapezius) need direct strengthening via banded waiter walks, push-up holds, bear crawls, and power raises so the scapula stays fixed while the arm accelerates.', 'experience', 'moderate', 'baseball', '{"power_raise_reps": "10+", "power_raise_load_lb": "15-20"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Posterior rotator cuff strengthening via seated dumbbell external rotation should progress toward 10% of body weight for 10 reps to build deceleration capacity and reduce impingement risk.', 'experience', 'moderate', 'baseball', '{"load_pct_bw": 10, "reps": 10}'::jsonb),
  ('sport-baseball', 'seasons', 'In-season arm-care/strengthening work should be pure maintenance at minimum effective dose and should not produce soreness; real strength gains belong in the offseason where soreness is acceptable.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Post-throwing is the preferred time for arm care for compliance, but should shift to the next day after very high pitch counts since a fatigued arm needs recovery, not more loading.', 'experience', 'hedged', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Baseball players'' traditional avoidance of resistance training is dismissed as an outdated myth; the speaker argues lifting is necessary for on-field speed and reactiveness, not just genetic quickness.', 'experience', 'strong', 'baseball', NULL),
  ('sport-baseball', 'power', 'Banded lateral (side) jumps train rapid unilateral cutting force for fielding and base-running; prescribed twice weekly for 4-5 sets of 3-4 reps per side.', 'experience', 'moderate', 'baseball', '{"frequency": "2x/week", "sets": "4-5", "reps": "3-4"}'::jsonb),
  ('sport-baseball', 'power', 'Because bases are only 90 feet apart, baseball speed is framed as almost entirely acceleration/drive-phase, so training should prioritize drive-phase power over top-end speed work.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'power', 'Dumbbell single-leg squats are prescribed 1-2x/week for 5 sets of 6-7 reps per leg to build the glute/quad drive-phase strength that improves base-stealing acceleration.', 'experience', 'moderate', 'baseball', '{"frequency": "1-2x/week", "sets": 5, "reps": "6-7"}'::jsonb),
  ('sport-baseball', 'power', 'Drop cossack squats build lateral hip power for cutting and reaching in the field; recommends 2-3 weeks of standard cossack squats before progressing to the lighter-loaded drop variation.', 'experience', 'hedged', 'baseball', '{"progression_weeks": "2-3"}'::jsonb),
  ('sport-baseball', 'power', 'Power clean and full clean are rated the top baseball speed exercises for training rapid force absorption/production and hip coordination, prescribed 2-3x/week as doubles or low-rep sets.', 'experience', 'strong', 'baseball', '{"frequency": "2-3x/week"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Rushed J-Band/warm-up routines fail to deliver motor control benefits; slowing a routine from 1-2 minutes to 3-5 minutes meaningfully improves activation and stabilizer training before throwing.', 'experience', 'moderate', 'baseball', '{"duration_before_min": "1-2", "duration_after_min": "3-5"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Letting the elbow dump in front of the shoulder during band rows/presses/flies (''humeral anterior glide'') reinforces the anterior laxity pitchers already have, raising risk of biceps-tendon and SLAP injury.', 'mechanistic', 'strong', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Compensating with rib-cage/trunk movement to finish band-routine reps instead of true scapular/shoulder end-range motion undermines the drill''s purpose and should be corrected by keeping the trunk controlled.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Internal-rotation band work should not be capped at 90 degrees for healthy pitchers; training the fuller external/internal rotation range used in the actual throw builds more usable stability, given control.', 'experience', 'hedged', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'A joint-by-joint band-routine progression (wrist/forearm through elbow, scapula, shoulder, rotator cuff) at roughly 5-10 reps per drill is prescribed to prime the same stabilizers used in pitching before throwing.', 'experience', 'moderate', 'baseball', '{"reps_per_exercise": "5-10"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Pre-throw band-routine work should stay sub-maximal and control-focused; actual strengthening overload of the same stabilizer muscles belongs in separate lifting or post-throw work, not the warm-up itself.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'FCU, pronator teres, and flexor digitorum are highlighted as key anterior/medial forearm UCL stabilizers, especially loaded during the pronation/supination transitions of breaking pitches.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Serratus anterior training via a banded overhead reach with forward trunk hinge is emphasized because proximal scapular stability is required to generate distal arm speed safely.', 'mechanistic', 'strong', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Programming priority for baseball players should follow a ~5,700-respondent survey weighting: shoulder/elbow 44%, hips/groin 31%, core/trunk 25%, reflecting throwing/bat control, power transfer, and rotational tracking respectively.', 'experience', 'moderate', 'baseball', '{"shoulder_elbow_pct": 44, "hips_groin_pct": 31, "core_trunk_pct": 25, "n_respondents": 5700}'::jsonb),
  ('sport-baseball', 'selection', 'Slow-eccentric dumbbell external rotation is called one of the best baseball exercises since players are typically far weaker here than in pressing/pulling; prescribes 4 sets of 5-7 reps.', 'experience', 'moderate', 'baseball', '{"sets": 4, "reps": "5-7"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Rotational forearm-roller work and Zottman curls are framed as elbow-protective grip/forearm training that also improves throw and bat command, prescribed around 4 sets of 12 reps.', 'experience', 'moderate', 'baseball', '{"sets": 4, "reps": 12}'::jsonb),
  ('sport-baseball', 'selection', 'Baseball players should progress to full-range barbell single-leg squats rather than staying with goblet squats only, since single-leg strength underlies the sport''s dominant movement patterns.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'power', 'Power clean and power snatch are prescribed as top ''impulse'' lifts for hitting, fielding reaction, and release speed, citing a high-school player power-snatching about 80 kg with a 40-inch vertical.', 'experience', 'moderate', 'baseball', '{"power_snatch_kg": 80, "vertical_in": 40}'::jsonb),
  ('sport-baseball', 'selection', 'Bench pressing up to roughly 275-300 lb is described as safe and non-harmful for a baseball player''s throwing, countering the belief that upper-body strength work ruins throwing mechanics.', 'experience', 'hedged', 'baseball', '{"bench_upper_bound_lb": "275-300"}'::jsonb),
  ('sport-baseball', 'power', 'Loaded rotational trunk work (glute-ham reach-and-rotate) plus single-arm overhead ab-roller holds are prescribed to build the trunk control and rotational speed needed to transfer hip power into the throw/swing.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'High-speed reactive shoulder drills such as the drop external-rotation catch are recommended less frequently closer to the competitive season due to the high joint speeds and stress involved.', 'experience', 'hedged', 'baseball', NULL),
  ('sport-baseball', 'power', 'Pitching velocity sits at the fast, light-load end of the force-velocity spectrum, so heavy strength training gives diminishing returns for velocity gains once an athlete passes a moderate strength threshold.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'power', 'Programming for velocity should progress along a force-velocity continuum, using underload throws with balls as light as 2-4 ounces as more specific to peak throwing speed than heavy barbell lifts.', 'mechanistic', 'moderate', 'baseball', '{"underload_ball_oz_min": 2, "underload_ball_oz_max": 4}'::jsonb),
  ('sport-baseball', 'weight_management', 'An elite hard-throwing reliever''s fastball velocity showed no consistent relationship to his bodyweight over an 11-year career; his two hardest-recorded pitches came at bodyweights 30 pounds apart.', 'experience', 'moderate', 'baseball', '{"bodyweight_lbs": [185, 215], "velocity_mph": 105}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Restricting an elite-velocity reliever to almost always one-inning outings, rarely two or more, is credited as central to his avoiding major arm injury despite historically elite fastball velocity.', 'experience', 'moderate', 'baseball', '{"multi_inning_outings": "15 of 563 games >=2 innings"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Good throwing mechanics that avoid early trunk rotation, poor arm position at foot strike, and a weak leg block reduce elbow and shoulder stress more than simply reducing velocity does.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Extreme joint mobility and fascial elasticity are described as prerequisites for tolerating bodybuilder-style heavy lifting without losing throwing range of motion, so lift selection should be individualized to an athlete''s mobility.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'seasons', 'In-season football lifting frequency should flip between three sessions a week against a weaker opponent and two sessions against a stronger one, adjusted weekly by strength of schedule.', 'experience', 'moderate', 'football', '{"days_per_week_weak_opponent": 3, "days_per_week_strong_opponent": 2}'::jsonb),
  ('sport-baseball', 'seasons', 'A three-day in-season week is built as leg-power day, upper-body power day, then a lighter athlete jump/plyometric day, with day one scheduled the day right after a game.', 'experience', 'moderate', 'football', NULL),
  ('sport-baseball', 'seasons', 'Facing a tougher opponent, in-season training drops to two lifting days and cuts volume sharply on the main lift (e.g. five sets of five becomes five sets of two) to minimize residual fatigue.', 'experience', 'moderate', 'football', '{"volume_easy_week": "5x5", "volume_hard_week": "5x2"}'::jsonb),
  ('sport-baseball', 'seasons', 'A 12-week in-season football block is split into about 8 weeks of a higher-volume comprehension phase and 4 weeks of a lower-volume, higher-intensity ascension phase, cycled weekly by opponent difficulty rather than peaking once.', 'experience', 'moderate', 'football', '{"comprehension_weeks": 8, "ascension_weeks": 4, "total_weeks": 12}'::jsonb),
  ('sport-baseball', 'selection', 'In-season power-day lifts open with a low-volume technical Olympic-lift variation (hang clean/snatch) to prime the nervous system, then an absolute-strength lift like back squat or bench, then hypertrophy/accessory work.', 'experience', 'moderate', 'football', NULL),
  ('sport-baseball', 'power', 'In-season plyometric athlete-day volume is deliberately minimized close to gameday, e.g. one hurdle hop instead of a series of three or four, to stay explosive without adding fatigue before competition.', 'experience', 'moderate', 'football', NULL),
  ('sport-baseball', 'selection', 'Bodybuilding-style accessory lifts (curls, extra hypertrophy work) are included in the in-season upper-power day partly for psychological/confidence effect, to make players feel big and look intimidating, not purely for performance.', 'experience', 'hedged', 'football', NULL),
  ('sport-baseball', 'injury_prevention', 'A pitcher can never raise fastball velocity without also raising elbow torque, so arm-specific strength (rotator cuff and grip force relative to mph) must rise alongside any velocity gain to offset injury risk.', 'mechanistic', 'strong', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Unmonitored weighted-ball-only velocity programs can build arm speed mainly by increasing layback range of motion (laxity) rather than strength, which raises elbow/shoulder stress; heavy-ball work should be paired with strength gains, not run alone.', 'mechanistic', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Cuff strength ratio (external vs internal rotation) should stay near 0.85-1.05; ratios skewed toward external rotation as high as 1.4 are linked to earlier in-game velocity drop-off and elbow/labrum injury.', 'experience', 'moderate', 'baseball', '{"ERI_target_range": "0.85-1.05", "ERI_observed_high": 1.4}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Throwing-arm rotator and grip strength should be tested fresh and again roughly every 72 hours (or post-outing) to separate true weakness from fatigue, then that day''s throwing/lifting volume should be reduced when strength tests low.', 'experience', 'moderate', 'baseball', '{"retest_interval_hours": 72}'::jsonb),
  ('sport-baseball', 'selection', 'An internal organizational analysis found pitchers drafted for clean, textbook mechanics led the league in arm injuries, while pitchers flagged for a mechanical fault (inverted-W arm action) had zero injuries over the same period.', 'cited_study', 'strong', 'baseball', NULL),
  ('sport-baseball', 'selection', 'Mechanical changes should be reserved for pitchers who are in pain or underperforming; when a change is warranted, intervene at the earliest phase of the delivery (leg lift, initial move) rather than late, ball-release-phase positions.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'power', 'Velocity-training load should be individualized by an athlete''s mass-vs-arm-speed profile: high-arm-speed, lower-mass throwers gain more from adding body mass, while strong, high-mass but slower-armed throwers gain more from moving lighter loads faster.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'weight_management', 'A study at Louisiana Tech found lean mass correlated with fastball velocity better than body-fat percentage did; each pitcher still has an individual body-fat/mass sweet spot for peak velocity found only through supervised experimentation.', 'cited_study', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Get the surgically repaired elbow moving early within pain-free range (rather than fully immobilized for 6-12 weeks) to prevent excess scar-tissue buildup that can permanently limit range of motion.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Elbow-surgery rehab should follow a fixed sequence: swelling control, full range of motion, joint stability/strength, a valgus-stress pseudo-throwing bridge, then return-to-throw, then return to competition, abbreviated but never skipped for minor injuries.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'A throwing program should not begin until grip and arm strength return near baseline post-surgery; throwing while grip strength is still very weak risks putting the repair under premature stress.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Distance-only return-to-throw plans are a weak stress proxy since athletes self-regulate intensity poorly; layering in a radar-gun velocity band, and ideally arm-sensor load data, at each distance gives much finer control of arm stress.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'A conservative post-elbow-surgery return-to-throw progression targets roughly a 2-3 mph increase per week on radar-tracked throws, erring toward feeling too easy rather than pushing to the edge of same-week recovery capacity.', 'experience', 'moderate', 'baseball', '{"mph_increase_per_week": "2-3"}'::jsonb),
  ('sport-baseball', 'injury_prevention', 'Rehab footwork and drill selection should be individualized to each pitcher''s mechanical needs rather than issuing one generic footwork pattern to every athlete, since a uniform plan works for average cases but not complex ones.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'A pain-free bullpen does not mean a pitcher is game-ready; velocity, command, off-speed control and work capacity must also return, and organizational pressure to rush a comeback raises re-injury risk after major elbow surgery.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-baseball', 'injury_prevention', 'Post-surgical scar tissue should be actively treated, since it can tether the ulnar nerve and block normal tissue sliding during throwing; described treatments include fascial abrasion technique and dry needling of the scar itself.', 'experience', 'moderate', 'baseball', NULL),
  ('sport-football', 'seasons', 'In-season lifting frequency should flex with opponent difficulty: 2 sessions (harder week, easy 2nd day) vs 3 sessions against weaker teams, including a short 20-30 min technical shakeout day.', 'experience', 'moderate', 'football', '{"sessions_per_week": "2-3", "shakeout_duration_min": "20-30"}'::jsonb),
  ('sport-football', 'seasons', 'In-season sessions should stay short (40-45 minutes) with just 3-4 exercises emphasizing big transferable lifts, since two-hour practices already fatigue players and longer sessions risk overuse injury.', 'experience', 'strong', 'football', '{"session_duration_min": "40-45", "exercises_per_session": "3-4"}'::jsonb),
  ('sport-football', 'injury_prevention', 'Coach observed knee pain and shin splints linked to hard, non-turf practice fields combined with too much in-season squat volume, prompting a reduction in squatting for that team.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'injury_prevention', 'In-season programming should target position-specific recurring problem areas (distinct issues for receivers vs. linemen) identified over time, rather than one generic template for the whole team.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'seasons', 'In-season rep schemes should favor cluster sets (near-max singles/doubles with about 30 seconds rest between reps) and EMOM-style work over generic straight sets like 3x10 or 5x5.', 'experience', 'moderate', 'football', '{"intra_cluster_rest_sec": "30"}'::jsonb),
  ('sport-football', 'injury_prevention', 'Adding light bodybuilding-style pump work in-season aids athletes'' mental engagement with training and can double as targeted injury-prevention isolation work for shoulders, knees, and back.', 'experience', 'hedged', 'football', NULL),
  ('sport-football', 'selection', 'For linebackers, absolute strength (squat, clean, bench, pull-up) is the top priority since greater strength directly improves the ability to defeat blocks from guards, fullbacks, and tight ends.', 'experience', 'moderate', 'football', '{"example_clean_lb": "350 vs 275", "example_squat_lb": "500 vs 350"}'::jsonb),
  ('sport-football', 'selection', 'Linebacker lateral speed is trained through glute strengthening, hip mobility work, and lateral drills; the coach even suggests secondary sports like tennis to build side-to-side quickness.', 'experience', 'hedged', 'football', NULL),
  ('sport-football', 'power', 'Reactive plyometric drills (e.g., hurdle hops, single-leg lateral hop combinations) are prioritized for linebackers as the second-most important quality, to speed up reading and reacting to plays.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'power', 'Track-style acceleration mechanics (forward lean, arm drive, shin angle) are trained deliberately for linebackers, considered the top skill because they convert strength and reactivity into field speed.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'seasons', 'Football''s off-season window for building strength is only about 5-6 months (December-April) before spring ball, shorter still for multi-sport athletes, requiring efficient early prioritization of work.', 'experience', 'moderate', 'football', '{"offseason_length_months": "5-6"}'::jsonb),
  ('sport-football', 'selection', 'Absolute strength (squat, bench, incline, single-leg squat) should be the foundation of the off-season program for every position, trained hard in the first two to three months.', 'experience', 'strong', 'football', '{"initial_strength_block_months": "2-3"}'::jsonb),
  ('sport-football', 'selection', 'Early off-season hypertrophy work at 7-17 reps is used because higher-rep training is claimed to drive sarcoplasmic hypertrophy, building muscle that can express more force later.', 'mechanistic', 'hedged', 'football', '{"hypertrophy_rep_range": "7-17"}'::jsonb),
  ('sport-football', 'injury_prevention', 'Off-season hypertrophy blocks also target correcting position-specific structural imbalances, such as one-sided strength in linemen and receivers from stance asymmetry, before heavy loading ramps up.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'power', 'Contrast training pairs heavy back squats with plyometric work (about 2-3 minutes rest between) specifically to convert absolute strength gains into speed and power.', 'experience', 'moderate', 'football', '{"rest_between_pairing_min": "2-3"}'::jsonb),
  ('sport-football', 'selection', 'Olympic lift technique work (cleans, snatches) should be emphasized in the first 4-12 weeks of off-season rather than spending that time on generic conditioning.', 'experience', 'moderate', 'football', '{"technique_phase_weeks": "4-12"}'::jsonb),
  ('sport-football', 'conditioning', 'Coach argues early off-season blocks devoted purely to generic conditioning-style GPP work waste time better spent building technical lifting proficiency for later power transfer.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'power', 'Rate of coordination (first-step quickness) is trained late off-season via plyometrics and faster Olympic lift execution, layered on top of already-built strength and technique.', 'experience', 'hedged', 'football', NULL),
  ('sport-football', 'seasons', 'Off-season splits into two roughly 3-month blocks: an early block (Jan-May) targeting combine testing and spring ball at higher volume, then a later block (Jun-Aug) prepping for camp at lower volume, higher intensity.', 'experience', 'moderate', 'football', '{"program1_months": "Jan-May", "program2_months": "Jun-Aug"}'::jsonb),
  ('sport-football', 'seasons', 'In-season training uses about 2-3 lifting days tied to the game schedule (e.g., lower-body day after a Friday game, upper day two days later), adjusted by opponent strength.', 'experience', 'moderate', 'football', '{"in_season_lift_days_per_week": "2-3"}'::jsonb),
  ('sport-football', 'selection', 'Position-specific testing batteries (clean, squat, single-leg squat, bench, vertical jump, shuttle, 40) set early off-season priorities: skill players emphasize jump/shuttle/40, linemen emphasize clean/bench/squat.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'power', 'In-house testing found single-leg squat strength at 315 lb correlated with a 30-inch vertical jump about 92% of the time, used to justify prioritizing single-leg squat loading for power transfer.', 'experience', 'moderate', 'football', '{"single_leg_squat_lb": "315", "vertical_jump_in": "30", "correlation_pct": "92"}'::jsonb),
  ('sport-football', 'selection', 'Later off-season shifts the weekly split toward a dedicated speed day and athlete-specific day for skill positions, while adding an extra hypertrophy day for linemen and linebackers.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'power', 'The final pre-camp phase (roughly July-August) deliberately lowers lifting volume while raising intensity and plyometric/speed work, to peak power and speed heading into camp.', 'experience', 'moderate', 'football', NULL),
  ('sport-football', 'seasons', 'In-season lifting frequency and load should track how tough the upcoming opponent is: lift more against weak opponents, but keep the pre-game session lighter against tough opponents to stay fresh.', 'experience', 'moderate', 'football', NULL),
