  ('sport-wrestling', 'weight_management', 'Excessive weight-cutting that leaves wrestlers weak is discouraged; adequate creatine and protein intake should be maintained through the season.', 'experience', 'strong', 'wrestling', '{"protein_g_per_lb_bodyweight": 1}'::jsonb),
