  ('sport-wrestling', 'weight_management', 'Lightweight wrestlers run roughly 145 lb and under; heavyweights run roughly 170 lb+ in high school or 174 lb+ in college.', 'experience', 'moderate', 'wrestling', '{"lightweight_max_lb": 145, "heavyweight_min_lb_hs": 170, "heavyweight_min_lb_college": 174}'::jsonb),
  ('sport-wrestling', 'selection', 'Lightweights should prioritize relative, pound-for-pound strength; heavyweights should prioritize absolute strength in squat, bench, and weighted pull-ups/dips.', 'experience', 'strong', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Lightweights need rapid reactive explosiveness trained in longer bouts to mimic continuous scrambles; heavyweights need shorter general-reaction bouts.', 'experience', 'moderate', 'wrestling', '{"lightweight_sec": "15-30", "heavyweight_sec": "7-10"}'::jsonb),
  ('sport-wrestling', 'conditioning', 'Lightweights benefit most from interval endurance training mimicking scrambles; heavyweights should use cyclical low-impact modalities like sled, bike, rower, or swim.', 'experience', 'strong', 'wrestling', NULL),
  ('sport-wrestling', 'injury_prevention', 'Running or hill-sprint intervals are discouraged for heavy wrestlers because impact loading at their bodyweight risks knee, shin, and lower-back injury.', 'experience', 'moderate', 'wrestling', '{"bodyweight_lb": "240-250"}'::jsonb),
  ('sport-wrestling', 'selection', 'Prescribes bodybuilding-style high-rep, long-tension accessory work targeting lats, biceps, and forearms because these grip muscles are slow-twitch and transfer directly to mat control positions like collar ties.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Argues wrestlers should borrow specific bodybuilding techniques rather than adopt a full bodybuilder training model, since wrestling demands explosive power and relative strength that classic bodybuilding splits don''t build.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'conditioning', 'Uses short-rest, high-rep supersets (e.g. 20-30 rep dips/rope climbs, 30s rest) to build strength-endurance intended to sustain power output into the fatigued late stages of a match.', 'experience', 'moderate', 'wrestling', '{"reps": "20-30", "rest_sec": 30}'::jsonb),
  ('sport-wrestling', 'power', 'Prescribes heavy sled pulls with a steep forward chest/shin lean to build back-leg drive power specifically for the wrestling penetration step, likening it to a sprinter''s start.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Adds a unilateral box-jump variation to train front-leg power production for the split-stance penetration step, arguing top wrestlers generate power from both legs, not just the trail leg.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'injury_prevention', 'Claims unilateral jump training builds structural integrity that reduces injury risk over a wrestling career, framed as a secondary benefit of the front-leg power exercise rather than its main goal.', 'experience', 'hedged', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Prioritizes takedown-specific power exercises (sled pulls, unilateral jumps) over generic lower-body strength work, arguing the gap between elite and average wrestlers is penetration-step power, not raw strength.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Recommends a condensed conjugate structure (paired max-effort/dynamic-effort lifts) over a traditional 4-day split for grappling athletes, since heavy mat time already strains recovery capacity.', 'experience', 'moderate', 'general', NULL),
  ('sport-wrestling', 'power', 'Pairs dynamic-effort (max-speed, submaximal-load) lifts with max-effort strength work in the same session so speed and heavy-strength qualities are trained together rather than in separate blocks.', 'experience', 'moderate', 'general', NULL),
  ('sport-wrestling', 'conditioning', 'Sizes conditioning intervals to match the time domain of that day''s max-effort lift, e.g. a 15-20s max lift pairs with 15-20s conditioning intervals for 6-8 rounds.', 'experience', 'moderate', 'general', '{"interval_sec": "15-20", "rounds": "6-8", "rest_sec": "45-60"}'::jsonb),
  ('sport-wrestling', 'seasons', 'Lifting frequency should scale inversely with mat-time: hobbyists training 2-3x/week can handle 3-4 lifting sessions, while athletes training 4-5x/week (multiple daily sessions) should cut back to 2.', 'experience', 'moderate', 'general', '{"hobbyist_lifting_days": "3-4", "elite_lifting_days": 2}'::jsonb),
  ('sport-wrestling', 'injury_prevention', 'Dedicates an optional third training day to bulletproofing commonly injured grappling joints (neck, shoulders, low back, knees) with higher-rep, blood-flow-focused isolation work.', 'experience', 'moderate', 'general', NULL),
  ('sport-wrestling', 'selection', 'Prioritizes back/lat and grip training because wrestling''s pulling actions (collar ties, russian ties, knee picks) depend heavily on lat and grip strength and strength-endurance.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Trains lats explosively via a rope-climb plyometric specifically because lats are naturally slower-twitch than pecs/triceps, arguing explosive pulling power, not just strength, determines mat dominance.', 'mechanistic', 'moderate', 'wrestling', '{"sets": "4-5"}'::jsonb),
  ('sport-wrestling', 'selection', 'Heavier weight classes need greater absolute strength to handle larger opponents, while lighter weight classes need greater relative (pound-for-pound) strength and explosiveness.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Recommends fat-grip/thick-grip pulling variations, 5-6 sets of 12-17 reps per side, to build grip and forearm strength that transfers directly to wrist-control and collar-tie positions.', 'experience', 'moderate', 'wrestling', '{"sets": "5-6", "reps": "12-17 per side"}'::jsonb),
  ('sport-wrestling', 'selection', 'Prescribes false-grip (thumb-over-bar) pull-ups, weighted 4-5 sets of 3-4 reps plus 2 sets to failure, to rehearse the exact hand position used in a collar tie.', 'experience', 'moderate', 'wrestling', '{"sets": "4-5", "reps": "3-4", "extra_sets_to_failure": 2}'::jsonb),
  ('sport-wrestling', 'conditioning', 'Uses high-rep sets (4x30-40) of an upper-back exercise to build lat/rear-delt strength-endurance meant to replicate the fatigue felt in the fourth-through-sixth minute of a match.', 'experience', 'moderate', 'wrestling', '{"sets": 4, "reps": "30-40"}'::jsonb),
  ('sport-wrestling', 'selection', 'Prioritizes low sled pushes to build the hip-level change and steep shin angle needed to finish low single-leg takedowns.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Programs two-inch-rope sled pulls for explosive grip, bicep and lat power that carries to arm drags and collar ties, 2-3x weekly, 4-5 sets of 20-30 meters.', 'experience', 'moderate', 'wrestling', '{"frequency_per_week": "2-3", "sets": "4-5", "distance_m": "20-30"}'::jsonb),
  ('sport-wrestling', 'selection', 'Uses sled curls to coordinate hip extension with rapid elbow flexion for hitting underhooks, prescribed 4-6 sets for 15-20 total reps.', 'mechanistic', 'moderate', 'wrestling', '{"sets": "4-6", "reps_total": "15-20"}'::jsonb),
  ('sport-wrestling', 'power', 'Varies sled-harness bear-crawl load: light for speed development of the penetration step, heavy (6-8 plates) to rehearse positions under simulated fatigue.', 'experience', 'moderate', 'wrestling', '{"heavy_load_plates": "6-8"}'::jsonb),
  ('sport-wrestling', 'selection', 'Selects dips to build tricep and pec strength for pummeling and hand-fighting, prescribed twice weekly for 5-6 sets of 7-15 reps.', 'experience', 'moderate', 'wrestling', '{"frequency_per_week": "2", "sets": "5-6", "reps": "7-15"}'::jsonb),
  ('sport-wrestling', 'selection', 'Builds toward handstand push-ups, progressing from floor to elevated feet, to develop overhead shoulder stability needed for collar ties and shot entries, once weekly.', 'mechanistic', 'moderate', 'wrestling', '{"frequency_per_week": "1", "sets": "4-6", "reps": "7-10"}'::jsonb),
  ('sport-wrestling', 'selection', 'Uses pistol squats to build single-leg strength and ankle/hip mobility that supports level changes and turning a defended shot into a scoring switch.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Sets pull-up benchmarks by weight class, 25-30 reps under 185-190 lb and roughly 10-15 fresh reps for heavyweights, since pulling strength carries to underhooks and cradles.', 'experience', 'strong', 'wrestling', '{"sub_185lb_reps": "25-30", "heavyweight_reps": "10-15"}'::jsonb),
  ('sport-wrestling', 'power', 'Prescribes knee-to-tuck jumps twice weekly, 4-7 sets of 3-4 reps, to train rapid hip extension for scrambles and explosive stand-ups from the down position.', 'experience', 'moderate', 'wrestling', '{"frequency_per_week": "2", "sets": "4-7", "reps": "3-4"}'::jsonb),
  ('sport-wrestling', 'seasons', 'Loads medicine-ball slams heavier, up to about 25 lb, in the off-season to build mass and strength, then lightens to 12-15 lb in-season to emphasize speed.', 'experience', 'moderate', 'wrestling', '{"offseason_lb": "25", "inseason_lb": "12-15"}'::jsonb),
  ('sport-wrestling', 'power', 'Treats off-season heavy lifts like squat and bench as building the strength base, while separate explosive drills convert that strength into speed within the same block.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Prescribes power snatch 3-4 times weekly in the off-season as light technical doubles to build hip and thoracic extension for the overhead collar-tie position.', 'mechanistic', 'moderate', 'wrestling', '{"frequency_per_week": "3-4"}'::jsonb),
  ('sport-wrestling', 'power', 'Uses lateral bounding onto a box twice weekly, 5 sets of 4 reps per leg, to train multidirectional explosiveness that sets up the penetration step.', 'experience', 'moderate', 'wrestling', '{"frequency_per_week": "2", "sets": "5", "reps": "4"}'::jsonb),
  ('sport-wrestling', 'power', 'Programs explosive push-ups to boxes twice weekly, 5 sets of 6-7 reps, to build rapid force output for pummeling and hand-fighting.', 'experience', 'moderate', 'wrestling', '{"frequency_per_week": "2", "sets": "5", "reps": "6-7"}'::jsonb),
  ('sport-wrestling', 'power', 'Considers the behind-the-neck split jerk the highest force-output lift available and includes it once or twice weekly when jerk boxes exist, citing carryover to the mat''s split stance.', 'mechanistic', 'strong', 'wrestling', '{"frequency_per_week": "1-2"}'::jsonb),
  ('sport-wrestling', 'power', 'Uses hip-banded pull-ups for accommodating resistance to build explosive pulling power, e.g. heavy sets of 3 followed by maximal-speed sets of 5.', 'mechanistic', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'selection', 'Targets off-season strength and explosiveness as wrestlers'' typical weak points, since they already accumulate plenty of conditioning through mat practice and prefer cardio work.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Uses higher-rep clean complexes off boxes, 3-4 building sets of 2 then 2 top sets of 5, to train repeated maximal power output for in-match scrambles.', 'experience', 'moderate', 'wrestling', '{"sets_build": "3-4", "reps_build": "2", "sets_top": "2", "reps_top": "5"}'::jsonb),
  ('sport-wrestling', 'power', 'Prescribes a lateral-bound plus single-leg-drive plus sprint combination, 5 sets of 2 reps per side, to train the rapid change of direction that sets up takedowns.', 'experience', 'moderate', 'wrestling', '{"sets": "5", "reps_per_side": "2"}'::jsonb),
  ('sport-wrestling', 'power', 'Supersets unilateral stair jumps with a mixed unilateral-to-bilateral hurdle jump series for 4 sets to train the penetration step and coordination across multiple angles.', 'experience', 'moderate', 'wrestling', '{"sets": "4"}'::jsonb),
  ('sport-wrestling', 'selection', 'Uses an isometric split-stance lunge with shaking dumbbells or kettlebells to build the dynamic trunk control elite wrestlers use to resist being controlled in the tie-up.', 'experience', 'moderate', 'wrestling', NULL),
  ('sport-wrestling', 'power', 'Finishes with jump lunges onto a box, 4 sets of 4 then 4 sets of 3 per leg, to convert trunk-control work into explosive split-stance power.', 'experience', 'moderate', 'wrestling', '{"sets_reps": "4x4 then 4x3 per leg"}'::jsonb),
  ('strength-accessories', 'necessity', 'Isolation exercises reliably drive the target muscle to failure since no other muscle can limit the set, giving more consistent, complete stimulus to that muscle than compound lifts provide.', 'mechanistic', 'strong', NULL, NULL),
  ('strength-accessories', 'necessity', 'In compound lifts, secondary or stabilizer muscles often aren''t recruited to failure, so relying only on compounds may under-stimulate contributing muscles that isolation work could target directly.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Per bi-articular muscle theory, hamstrings aren''t maximally recruited during squats because hip and knee actions oppose each other, so back extensions or leg curls are needed to fully train them.', 'mechanistic', 'hedged', NULL, NULL),
  ('strength-accessories', 'cautions', 'Compound lifts create more local and systemic fatigue than isolation work, so adding volume via extra heavy squat/deadlift sets is often less feasible than adding isolation sets for the same muscle.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'placement', 'General template: use compound lifts to cover major movement patterns, then add isolation lifts afterward to target muscles the compounds didn''t stimulate to their full potential.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Muscles only indirectly involved in a compound lift, like triceps during pressing, get a smaller training effect than the prime mover and may need direct work to develop fully.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Anatomical structure determines how much an accessory muscle is recruited in a compound lift; rear delts are substantially worked by rowing while biceps are not, so under-recruited muscles need direct isolation training.', 'mechanistic', 'hedged', NULL, NULL),
  ('strength-accessories', 'necessity', 'Accessory exercises exist to build muscle, improve durability, and fix weak points supporting the squat, bench, and deadlift, which remain the true drivers of powerlifting performance.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'cautions', 'Taking every accessory set to failure or max RPE adds training fatigue without a proportional stimulus benefit and misses the actual purpose of accessory work for a competitive lifter.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'dose', 'Heavier, multi-joint accessory lifts (RDLs, good mornings, split squats, leg press, hack squat, DB/machine pressing) should generally be kept to about 2-3 reps in reserve, RPE 7-8.', 'experience', 'strong', NULL, '{"reps_in_reserve": "2-3", "rpe": "7-8"}'::jsonb),
  ('strength-accessories', 'dose', 'Smaller, single-joint accessories like lateral raises or pushdowns can be trained closer to failure more often, e.g. taking the last set to failure within an 8-15 rep range, without hurting main-lift progress.', 'experience', 'strong', NULL, '{"rep_range": "8-15"}'::jsonb),
  ('strength-accessories', 'placement', 'Pushing for PRs on bigger accessory lifts is appropriate mainly during a planned deload week after primary work is finished, not during early weeks of a training cycle.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'cautions', 'A coached powerlifter who chased a heavy, low-rep (3-6 rep) tricep-pushdown PR injured his elbow, disrupting his bench training and costing progress toward his goal despite his overall gains.', 'experience', 'strong', NULL, '{"rep_range": "3-6"}'::jsonb),
  ('strength-accessories', 'placement', 'As competition nears, deprioritize heavy compound-style accessory variations and shift remaining accessory work toward machine or single-joint isolation exercises, which create less fatigue that could interfere with the main lifts.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Anecdotally, lifters who far outperformed the speaker on accessory lifts like dumbbell incline press only slightly outperformed him on competition bench, suggesting heavy accessory investment doesn''t proportionally transfer to competition strength.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Isolation exercises are needed because compound lifts can''t fully train muscles like the rectus femoris, whose hip-flexion action cancels out during squats since hip and knee extension oppose its stretch.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'A 24-week trial in trained women found arm size grew most in groups doing direct isolation curls/triceps work, while compound-only training grew quads/glutes best — exercise choice should match target muscle.', 'cited_study', 'strong', NULL, '{"duration_weeks": 24}'::jsonb),
  ('strength-accessories', 'cautions', 'Compound lifts are generally more physiologically and psychologically fatiguing and more stressful on joints than isolation work, since isolation uses lighter loads, fewer muscles, and lower technical/cardio demand.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'placement', 'Best practice for hypertrophy combines both lift types in one program: compounds for time-efficient overall stimulus, isolation for full regional development, lower fatigue, and lower joint stress.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Front delts often need little or no direct isolation work since heavy compound pressing already provides sufficient indirect stimulus — isolation should target muscles compounds under-train, not ones already covered.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Controlled trials adding biceps curls or triceps extensions to a bench press plus lat pulldown program produced no extra elbow-flexor or arm-circumference growth versus compound-only training over 8-10 weeks.', 'cited_study', 'strong', NULL, '{"duration_weeks": "8-10"}'::jsonb),
  ('strength-accessories', 'necessity', 'Regional hypertrophy is real: an 8-week trial in 22 trained men found varying exercises (including isolation) across training days grew more muscle regions than repeating the identical routine each session.', 'cited_study', 'strong', NULL, '{"n": 22, "duration_weeks": 8}'::jsonb),
  ('strength-accessories', 'selection', 'Lateral delts and calves need direct isolation work (lateral raises, calf raises) because no compound lift meaningfully produces the shoulder-abduction or ankle-plantarflexion motions that grow those muscles.', 'mechanistic', 'strong', NULL, NULL),
  ('strength-accessories', 'selection', 'Leg curls (knee flexion) are likely necessary for full hamstring development since compound lifts mainly train the hip-extension function of the hamstrings, not their separate knee-flexion role.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Leg extensions or reverse Nordic curls are likely needed to grow the rectus femoris, since compound quad lifts like squats develop the vasti heads well but largely miss this muscle.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Triceps long-head isolation (skull crushers, overhead extensions, rope pushdowns) is likely necessary because pressing movements shorten the long head via shoulder extension on the descent, limiting its force output and growth.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Overall conclusion: compound-only training is insufficient for complete muscle development because several muscles and muscle regions are not optimally trained by any compound lift, making isolation work necessary.', 'cited_study', 'strong', NULL, NULL),
  ('strength-accessories', 'cautions', 'Several studies supporting ''isolation adds nothing to compound training'' (Barbalho et al.) are flagged as containing improbable, likely illegitimate data and should not be trusted as evidence.', 'cited_study', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Assistance lifts strengthen core lifts through three mechanisms: better hypertrophy stimulus-to-fatigue ratio, targeted weak-point strengthening, and fatigue/psychological relief from repetitive competition-style lifting.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'selection', 'For a weak bench lockout, partial-range work like board press, pin press, or rack press directly trains that range, since full-range bench accumulates fatigue before reaching lockout and trains it poorly.', 'mechanistic', 'strong', NULL, NULL),
  ('strength-accessories', 'dose', 'Assistance lifts must ''earn their keep'': include one only to fix an identified specific weak point or lagging muscle; absent such a problem, core-lift training is the better use of time.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'placement', 'Recommended periodization: beginners train almost entirely with core lifts; hypertrophy phase relies heavily on assistance work with reduced/no core lifting; strength phase flips to mostly core plus targeted assistance; peaking is almost all core lifts.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'placement', 'During a hypertrophy phase, heavy overload can run through a variant lift (high-bar squat) while the competition lift (low-bar squat) stays light for technique, easing the return to heavy work later.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'cautions', 'Assistance and variation lifts are often misused as a substitute for proper fatigue management — swapped in because core lifts are being overloaded with poor volume/frequency, sacrificing specificity and blunting long-term core-lift gains.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'cautions', 'Assistance-lift gains don''t reliably transfer to the core lift, and predicting which will is largely guesswork; the speaker''s own three-month, ~90 lb dip-strength gain produced zero bench press improvement.', 'experience', 'strong', NULL, '{"duration_months": 3, "added_load_lbs": 90}'::jsonb),
  ('strength-accessories', 'necessity', 'In the short term, nothing improves a core lift as directly as practicing that lift itself, since the relevant anatomical and technical adaptations are lift-specific; assistance work plays a secondary role.', 'mechanistic', 'strong', NULL, NULL),
  ('strength-accessories', 'necessity', 'Biarticular muscles like the hamstrings see little growth from squats because opposing hip/knee actions cancel out net muscle-length change; a 10-week deep-vs-shallow squat trial in 17 men found hamstrings barely grew either way.', 'cited_study', 'strong', NULL, '{"n": 17, "duration_weeks": 10}'::jsonb),
  ('strength-accessories', 'necessity', 'A 9-week trial (34 subjects) comparing squats to hip thrusts found glutes grew similarly in both despite not being the squat''s primary target, attributed to large range of motion rather than direct targeting.', 'cited_study', 'strong', NULL, '{"n": 34, "duration_weeks": 9}'::jsonb),
  ('strength-accessories', 'dose', 'Accessory-muscle growth from a compound lift scales with proximity to failure, range of motion, and dynamic vs isometric involvement; novices need less proximity to failure than advanced lifters to grow accessories.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'placement', 'Recommended approach: perform compound lifts to maximally stress only the primary target muscle, then use separate isolation exercises later in the session or week to fully train accessory muscles.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'cautions', 'Prefatiguing a target muscle with isolation before a compound lift (e.g., leg extensions before leg press) makes it reach failure sooner, which can reduce growth stimulus reaching secondary muscles like the glutes in that lift.', 'cited_study', 'moderate', NULL, '{"n": 24, "duration_weeks": 9}'::jsonb),
  ('strength-accessories', 'selection', 'Grip-width changes only marginally shift accessory involvement — triceps activation was slightly higher with medium/narrow bench grips than wide grip — so technique tweaks have limited power to redirect stimulus to accessories.', 'cited_study', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'Longer rest (roughly 2-4 min) is more effective for compound/main lifts, but shorter rest (about 1.5 min or less) works equally or better for isolation/accessory lifts, per cited studies.', 'cited_study', 'moderate', NULL, '{"compound_rest_min": "2-4", "isolation_rest_min": "<=1.5"}'::jsonb),
  ('strength-accessories', 'selection', 'Coach ranks seated/dead-stop good mornings as B-tier assistance, targeting weak points at deadlift lockout, squat mid-range, and the finish position of Olympic-style lifts.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Overhead triceps extension is said to recruit more high-threshold motor units due to the overhead angle, producing a stronger, more stable bench lockout.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Coach ranks overhead triceps extension and reverse hyper as A-tier accessories, rating seated good mornings only B-tier by comparison for powerlifters.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'Reverse hyper is dosed at roughly 10-17 reps per set, with load varied from heavy to light depending on the training goal.', 'experience', 'moderate', NULL, '{"reps": "10-17"}'::jsonb),
  ('strength-accessories', 'necessity', 'Many powerlifters are posterior-chain dominant with a weak anterior core; pairing reverse hyper with hanging knee raises is claimed to correct this and boost overall squat, bench, and pull strength.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'placement', 'Reverse hyper and hanging knee raises are prescribed as a paired combo in the same session, since the coach says they reinforce each other''s effect.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Muscle size is one of three drivers of strength; unlike neural efficiency and technique, hypertrophy is non-specific, so growing prime movers via accessory lifts still builds long-term strength.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'A short-term strength plateau results from maxed-out neural and technical efficiency from specific heavy lifting; the fix is shifting toward hypertrophy-focused accessory work to add muscle mass first.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'placement', 'Recommends periodizing so hypertrophy/accessory emphasis dominates early in a training cycle, then tapers as neural-efficiency/peaking work takes over approaching a strength test.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'Example 15-week/3-block cycle: block1 ~16 weekly quad/glute sets (1/4 from squats, 6-10 reps); block2 ~12 sets (half from squats, 4-8 reps); block3 ~8 sets (3/4 from squats, 1-3 reps).', 'experience', 'moderate', NULL, '{"block1_weekly_sets": 16, "block1_squat_fraction": 0.25, "block1_reps": "6-10", "block2_weekly_sets": 12, "block2_squat_fraction": 0.5, "block2_reps": "4-8", "block3_weekly_sets": 8, "block3_squat_fraction": 0.75, "block3_reps": "1-3"}'::jsonb),
  ('strength-accessories', 'cautions', 'Near a strength peak, accessory volume should drop to a low maintenance dose only, since added fatigue would otherwise interfere with maximal 1RM performance.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'Accessory lifts let a lifter accumulate hypertrophy volume with less joint stress than repeatedly loading heavy on the competition lift itself.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'One isolation exercise per muscle (biceps, triceps) is likely needed because compounds can''t maximize tension across the full muscle length, especially the triceps long head.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'After 4 sets to failure per isolation exercise, adding a 5th or 6th set produced no significant extra arm growth over 8 weeks; better to redirect volume elsewhere.', 'cited_study', 'moderate', NULL, '{"sets": "4 to 6", "duration": "8 weeks"}'::jsonb),
  ('strength-accessories', 'dose', 'Raising isolation volume from 8 to 12 fractional weekly sets per muscle is expected to add only about 0.9% extra growth per a cited meta-analysis, too small to detect via DEXA.', 'cited_study', 'moderate', NULL, '{"volume_range": "8 to 12 fractional sets/week", "expected_growth_diff": "~0.9%"}'::jsonb),
  ('strength-accessories', 'necessity', 'Published studies suggest adding isolation work to a compound movement yields only minimal extra arm growth, but the speaker''s own in-house meta-analysis of the same literature found a real, small benefit.', 'cited_study', 'hedged', NULL, NULL),
  ('strength-accessories', 'cautions', 'When sets are taken close to failure with short (about 1-minute) rest, extra sets on the same exercise add little because fatigue, not undertraining, becomes the limiting factor.', 'mechanistic', 'moderate', NULL, '{"rest": "~1 minute"}'::jsonb),
  ('strength-accessories', 'selection', 'In an off-season powerlifting ''bridge'' block, plyometric/explosive accessories (box jumps, dumbbell jumps, single-leg jumps, plyo push-ups) are prescribed alongside the main competition lift.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'necessity', 'Explosive accessory work is claimed to build force-production speed that carries over to the main lifts, such as explosiveness out of the squat hole or off the chest in bench.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'necessity', 'General athleticism and coordination built through sport-performance-style accessory work is claimed to help lifters make technical adjustments and recover from off positions, indirectly supporting heavier lifting.', 'experience', 'hedged', NULL, NULL),
  ('strength-accessories', 'placement', 'Accessories are performed in the same session immediately after that day''s main competition lift, with selection partly based on how fatigued the lifter already is.', 'experience', 'strong', NULL, NULL),
  ('strength-accessories', 'cautions', 'On multi-lift training days, lower-setup, easier accessories are deliberately chosen so accumulated fatigue doesn''t rob focus and effort from the accessory work.', 'experience', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'Rest between accessory sets is kept similar to top-set rest, about 2 minutes, shortened somewhat only for lower-intensity movements like box jumps.', 'experience', 'strong', NULL, '{"accessory_rest": "~2 minutes"}'::jsonb),
  ('strength-accessories', 'necessity', 'Some muscles, like the biceps, are biarticular and not maximally recruited during compound pulling exercises because those combine elbow flexion with shoulder extension, so isolation work is needed to fully train them.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'dose', 'Recommended approach: accumulate the majority of training volume from compound lifts, then add isolation work specifically for the muscle groups that compound exercises under-train.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'cautions', 'Avoid programming two heavy compound lifts, e.g. squat and stiff-leg deadlift, in the same session: shared stabilizer fatigue limits the second lift and required rest makes the session impractically long.', 'mechanistic', 'moderate', NULL, NULL),
  ('strength-accessories', 'selection', 'Exercise selection should favor movements with a good stimulus-to-fatigue ratio, a large range of motion, and tension maintained throughout, since these traits are claimed to drive more growth per unit of fatigue.', 'mechanistic', 'moderate', NULL, NULL),
  ('doc:2026-08-16-coach-audit-report', 'Coach Generator Audit — Grid × Trainer Swarm (2026-08-16)', '**Method.** The REAL `ProgramGenerator.generate()` (never a reimplementation) ran the full structural input grid — 162 programs across focus × days × experience, no-barbell gyms, session caps, cardio-heavy variants, fill-week, and seed rotation — against a frozen production catalog, via CI. 30 independent Sonnet-max reviewers in a science-first personal-trainer persona reviewed every program against `generator-evidence.json`, returning what/why/severity plus an `encodableRule` wherever the fix was deterministic. In parallel, 22 reviewers authored the 11-label catalog taxonomy for all 1,305 exercises (owner-approved; migration 20260816000002; 606 contentious rationales in `catalog-label-rationales.json`).', 'synthesis', 'strong', NULL, NULL),
  ('doc:2026-08-16-coach-audit-report', 'Coach Generator Audit — Grid × Trainer Swarm (2026-08-16)', '**Verdict on the pre-audit generator.** 162/162 programs reviewed: ratings 1★×6 · 2★×68 · 3★×62 · 4★×25 · 5★×1; 75 critical, 266 important, 51 minor issues; 382 encodable rules (highly convergent — independent reviewers kept finding the same defects).', 'synthesis', 'strong', NULL, NULL),
  ('doc:2026-08-16-coach-audit-report', 'Findings → shipped rules (all tested)', '1. **Novice intensity (most-repeated CRITICAL).** New lifters were opened at 90% 1RM with no established max. → Experience-scaled intensity ceilings (new 72.5 / intermediate 87.5 / advanced 92.5). 2. **%-vs-reps contradiction (systemic).** 90% printed beside a 6-rep target our own reps-at-percent table says 90% cannot support. → Anchor = `percentFor(range top)`, under the ceiling. 3. **Axial stacking (CRITICAL).** Squat + deadlift both at the top anchor in one session. → Only one heavy-spinal-load (label) main keeps the session''s top anchor; later ones drop ~10%. 4. **No weekly undulation.** The same lift at its top anchor every session. → Heavy/light wave: a lift keeps its top anchor ≤2×/week; further exposures drop ~10%. 5. **Conditioning goal failure.** `cardioDays=0` shipped ZERO zone work. → Every conditioning lifting day ends in a zone-4 interval finisher. 6. **Rep windows.** 15-re', 'synthesis', 'strong', NULL, NULL),
  ('doc:2026-08-16-coach-audit-report', 'Deferred (tracked)', '- Fatigue-cost-aware session-cap trimming (labels ready; consumer TBD). - Joint-stress filters ("work around my knee") — trainer-arm feature. - Sex-delta variants in the grid harness (unit tests cover the deltas; the corpus didn''t exercise them — add sex to the grid). - Cardio auto-periodization (minutes/intervals riding the week wave). - Audit-driven per-exercise focus-score corrections (targeted label updates as field feedback accumulates).', 'synthesis', 'strong', NULL, NULL),
  ('doc:2026-08-16-coach-audit-report', 'Deferred (tracked)', '**Artifacts.** Corpus + reviews + labels: session scratchpad `audit/`; permanent grid harness: `GeneratorGridDumpTests.swift` (GRIDJSON in every CI run). Swarm ops lesson: serialize swarms, waves of 4, small batches, file-based outputs — bursts die on rate limits and 64k output caps.', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Smith machines — corpus verdict', 'Owner question 2026-08-22: "How good are Smith machines for strength movements? I think they are incredible personally." Three-agent deep-read over the 12 densest Smith transcripts (RP ×4, Garage Strength, 3DMJ, House of Hypertrophy, Menno/Israetel, Data Driven): 72 findings. Raw: tools/youtube-research/passes/smith/f-*.json.', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Verdict: the owner is more right than the gym-bro consensus —', '**Hypertrophy: legitimately excellent.** RP''s own title is "It''s Not As Bad As You Think": external stability improves mind-muscle connection and lets you isolate a target better than free weights in some contexts. Smith squats robustly build quads/glutes/adductors; the feet-forward Smith squat is a DELIBERATE quad-bias tool (a hack-squat/ free-squat hybrid, 10–15 reps, 3–6" forward stance), not a compromise. Two of the corpus''s cited growth studies were themselves run on Smith benches (Akagi; Chavez 47-subject incline trial). The one mechanistic knock: rail friction shaves the eccentric slightly — real, minor.', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Verdict: the owner is more right than the gym-bro consensus —', '**Strength: the force is real; the skill is not transferable.** The cleanest data point in the pass: a lifter who trained legs for years on Smith hack squats returned to free squats with quad strength INTACT — only the free-squat skill had eroded. Muscle and force built on the rail count. What the rail never trains is balance/stabilizer control, so carryover to free lifts and sport is reduced; S&C coaches are right to steer field athletes away. Translation: Smith work builds strength, but a powerlifter still has to practice the competition lift.', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Verdict: the owner is more right than the gym-bro consensus —', '**The asterisks:** 1. **Not for beginners.** The rail happily loads positions a free bar would refuse (feet too far forward → knees/back strain that builds silently for weeks; good-morning cheating on squats). Foot placement IS the skill, and novices don''t have it. 2. **Pressing entrapment is WORSE, not better.** A pinned lifter can''t dump or tilt free the way an unclipped barbell allows; the corpus carries a 30-second-escape story. A spotter matters MORE on Smith presses. 3. **Athletes should skip it** — sport-prep demands the instability the rail removes.', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Verdict: the owner is more right than the gym-bro consensus —', '**Signature uses the corpus endorses:** quad-biased squat, incline bench (stability + length-biased curve), Bulgarian split squats (balance removed → more output to the target), chest-supported rows, overhead press for lagging front delts, back-pain-flare fallback (less spinal stabilization), solo high-volume pump work (fast re-rack).', 'synthesis', 'strong', NULL, NULL),
  ('doc:smith-machine', 'Generator alignment (shipped with this doc)', '1. Smith-named lifts get a complexity floor of 3 — gated away from NEW lifters (same soft mechanism as the Bosu safeguard; never a hole, and intermediates+ are untouched). 2. The sport_prep lens demotes Smith-named lifts (S&C consensus). 3. No hypertrophy/accessory demotion — the machine-first accessory ladder already favors it, and the corpus says that''s correct.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Sport-prep parameters — football / baseball / wrestling', 'Synthesis of the 2026-08-21 sport deep-read: 218 findings from 36 transcripts (12 per sport), read against `tools/youtube-research/ brief-sport.md` by a nine-agent swarm. Channel authority per sport: Garage Strength + Overtime Athletes (football), Driveline + Tread Athletics (baseball), Daru Strong + Garage Strength (wrestling). Raw findings: `tools/youtube-research/passes/sport-*/f-*.json`. A few football claims leaked into baseball batches via a shared-channel video; they are counted under football here.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Sport-prep parameters — football / baseball / wrestling', 'The point of this document: parameters the GENERATOR can consume for the `sport_prep` goal and the `inSeason` flag — not general sports science. Each sport section ends with its generator derivations.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Football', '**Season structure.** The off-season is short (~5-6 months) and splits in two: an early higher-volume strength/hypertrophy block (early work at 7-17 reps; squat twice weekly — one 5x7 volume day, one speed day; Olympic-lift TECHNIQUE emphasized in weeks 4-12 at light load before adding weight), then a pre-camp block at lower volume and higher intensity where plyometrics and speed peak. After the season: 2-3 weeks easy before ramping again.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Football', '**In-season.** 2-3 short sessions (40-45 min, 3-4 exercises, big transferable lifts), flexed by opponent difficulty — more/harder against weak opponents, lighter before tough ones (5x5 weeks vs 5x2 weeks). Cluster sets (near-max singles/doubles, ~30s intra-rest) over straight sets. Sprint-mechanics work INVERTS the usual pattern: 2-3x weekly in-season, ~1x off-season. Light pump work rides along for engagement + joint prophylaxis.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Football', '**Selection.** Absolute strength is the universal foundation (back + front squat, bench variants, cleans); the single-leg squat is the one exercise named top-tier for EVERY position (hip mobility + unilateral trunk control for cutting/blocking; an in-house 315 lb single-leg squat ↔ 30" vertical correlation is their justification). Explosive work = Olympic variations nearly daily off-season + contrast training (heavy squat paired with jumps, 2-3 min between) + plyo ≥2x weekly. Benchmarks scale by position (linemen clean 1.0-1.25x BW; skill positions lighter but faster; HS explosiveness bar ≈ 8 ft broad / 26-28" vertical; retest every 12-18 weeks).', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Football', '**Generator derivations (football):** - Off-season: explosive budget UP (2/day is defensible), squat patterns + Olympic-flavored pulls preferred, hypertrophy rep windows early block, intensity ramp late block. - In-season: session cap ~45 min, 3-4 exercises, mains only, low-rep cluster-style prescriptions, NO volume accessories; deload-by- schedule is normal, not a warning sign. - Unilateral quad pattern (split squat / single-leg squat) should rank up for sport_prep football regardless of focus. - Conditioning: none added beyond sprint work — practices carry it.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Baseball', '**The priority inversion.** Baseball S&C is arm-first: shoulder/elbow health outranks everything (a 5,700-athlete survey weighting cited as 44% shoulder/elbow, 31% hips/groin, 25% trunk). Arm care is its own subsystem, NOT generic lifting: posterior-cuff external rotation progressing to ~10% BW x 10 reps, external/internal rotation strength ratio held near 0.85-1.05, scapular stabilizers (serratus, low trap) trained in throwing-specific positions, forearm/FCU isometrics for UCL protection. Velocity work never runs without parallel arm strength (torque rises with every mph).', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Baseball', '**Selection.** In the weight room: GENERAL athleticism via compounds (squat, deadlift, bench) + sprint/plyo — explicitly NO sport-mimicry lifts. Slow-eccentric DB external rotation is the one accessory called out as near-universal (players are weakest there). Single-leg progressions matter (goblet → barbell). Catchers get less deep-squat volume (the position already loads it); heavy benching (275-300 lb) is defended as harmless to throwing.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Baseball', '**Season structure.** Off-season throwing runs on-ramp → ~6-week velocity phase → competition phase. In-season lifting is maintenance at MINIMUM effective dose and must not produce soreness; speed/power detrain fastest so the little work done preserves THOSE. Starters schedule proactively around the rotation (heaviest lift right after a start; brief power touch 2-3 days before the next); relievers and position players schedule reactively. Volume reduction scales with training age (veterans cut most).', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Baseball', '**Power.** Acceleration-dominant (90 ft between bases): drive-phase work, cleans 2-3x weekly, lateral/rotational power (banded side jumps, cossack progressions, rotational trunk work). Velocity itself lives at the fast end of the force-velocity curve — past a moderate strength threshold, heavy lifting gives diminishing velocity returns.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Baseball', '**Generator derivations (baseball):** - sport_prep baseball: shoulder-caution posture BY DEFAULT — no behind-neck pressing, prefer neutral-grip/landmine pressing angles; external-rotation accessory slotted like core (a standing dose). - In-season: lowest-volume maintenance of the three sports; no soreness = accessory sets minimal, mains submaximal, power touch preserved. - Rotational/lateral power patterns rank up; pure top-speed conditioning ranks down (game supplies it). - Catchers (position data unavailable to the generator today): note only.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**The four pillars.** Explosiveness/reaction, strength (RELATIVE for light classes, ABSOLUTE for heavy — ~500 lb squat named as the heavyweight bar), GRIP (its own pillar: fat-grip pulls 5-6x12-17, false-grip weighted pull-ups, sled curls for underhooks; pull-up benchmarks 25-30 reps under ~185, 10-15 for heavyweights), and strength-endurance (high-rep supersets at 30s rest to reach minutes-4-6 match fatigue).', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**Selection.** Unilateral-first is the law — stance, penetration step, and shot finishes are one-sided (split squats front-racked, goblet lunges weaker-leg-first, pistols, unilateral jumps and stair bounds). Sled work is the signature modality (low pushes for level change, heavy pulls for back-leg drive, harness crawls light-for- speed / heavy-for-fatigue-rehearsal). Lats/back and grip outrank pressing; a condensed conjugate shape (max-effort + dynamic-effort paired in one session) fits recovery better than a 4-day split. Optional third day: joint bulletproofing (neck, shoulders, low back, knees) at high reps.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**Season structure.** In-season KEEPS the big lifts in 40-45 min sessions rather than cutting them; the field''s named mistake is tapering too early and peaking before the postseason. Lifting frequency scales inversely with mat time (hobbyists 3-4, elite in-camp 2). Implement loads lighten in-season (25 lb med-ball → 12-15 lb) to shift the same drills toward speed.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**Conditioning splits by weight class.** Lightweights: interval work in scramble-length bouts (15-30s). Heavyweights: cyclical low-impact (bike/rower/sled/swim) — running and hill sprints are discouraged at 240+ lb bodyweights (impact injury risk).', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**Weight management.** Depleting cuts are rejected; keep protein (~1g/lb) and creatine through the season.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Wrestling', '**Generator derivations (wrestling):** - Unilateral variants rank ABOVE bilateral for sport_prep wrestling (the inverse of the default ladder). - Grip/lat emphasis: pulling accessories rank up; a grip-flavored accessory is a standing dose like baseball''s cuff work. - In-season: sessions stay 40-45 min WITH mains (unlike baseball''s minimum dose); intensity holds, volume trims; never zero out explosive work. - Conditioning style keys off bodyweight when known (body context fields, 2026-08-21): heavier athletes → low-impact cyclical, which composes with the existing impactCaution demotion.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Cross-sport consensus (the generator''s shared sport_prep spine)', '1. **In-season = short, intense, low-volume, mains-first.** All three sports converge on 40-45 min, 2-3x weekly, big lifts kept, volume (not intensity) as the release valve, flexed by schedule/opponent. 2. **Explosive work is a first-class citizen off-season** and the LAST thing zeroed in-season (it detrains fastest). 3. **The sport supplies conditioning.** Added conditioning is the exception (wrestling by weight class), not the rule. 4. **Sport-specific prophylaxis is a standing dose**: arm care (baseball), joint bulletproofing/neck (wrestling), position- specific pump work (football). 5. **No weight-room mimicry** (baseball says it outright; football and wrestling train positions via loading patterns, not sport charades) — the generator should bias PATTERNS, never invent sporty exercises.', 'synthesis', 'strong', NULL, NULL),
  ('doc:sport-prep-parameters', 'Follow-up code pass (not yet built)', 'Wire per-sport parameter sets into `GeneratorScience`/`ProgramGenerator` keyed off a `sportPrepSport` profile field: selection tilts (unilateral rank-up for wrestling, rotational/lateral for baseball), standing prophylaxis slots (cuff / grip), in-season prescription caps per sport, and conditioning style by weight class riding the body-context fields. Each knob lands with a no-dead-knobs test, same as every profile field.', 'synthesis', 'strong', NULL, NULL),
  ('doc:strength-accessories', 'Accessories for strength — corpus verdict', 'Owner challenge 2026-08-21: "Can you not train strength on isolation exercises?? Tricep work in isolation for strength is critical!" The generator''s strength filter stripped every isolation slot. Four-agent deep-read over the 16 densest transcripts from the strength-authoritative channels (Stronger By Science, Barbell Medicine, Juggernaut, Data Driven Strength, Westside, RP, Garage Strength): 70 findings. Raw: tools/youtube-research/passes/strength-accessories/f-*.json.', 'synthesis', 'strong', NULL, NULL),
  ('doc:strength-accessories', 'Verdict: the owner is right; the discipline is dose, not exclusion', '**Necessity (23 findings).** Assistance lifts strengthen core lifts via three mechanisms (RP, strong): better hypertrophy stimulus-to-fatigue than more heavy compound sets, targeted weak-point strengthening, and fatigue/psychological relief. Muscle size is a NON-specific strength driver — accessories build it at lower joint cost. Compounds anatomically under-train specific lift-critical muscles: hamstrings barely grow from squats (biarticular cancellation; 10-week trial), triceps long head is shortchanged by pressing (overhead extension rated A-tier for powerlifters — the owner''s exact example), anterior core is the classic posterior-dominant weak point (reverse hyper + hanging knee raise pairing).', 'synthesis', 'strong', NULL, NULL),
  ('doc:strength-accessories', 'Verdict: the owner is right; the discipline is dose, not exclusion', '**The counterweight (12 cautions).** Specificity still rules ("nothing improves a core lift like the lift"); accessory transfer is not guaranteed (+90 lb dip strength → zero bench improvement); accessories must EARN THEIR KEEP against an identified weak point; heavy multi-joint accessories stay at RIR 2-3 / RPE 7-8 (a lifter chasing a 3-6-rep pushdown PR injured his elbow); near a peak, accessory volume drops to maintenance.', 'synthesis', 'strong', NULL, NULL),
  ('doc:strength-accessories', 'Verdict: the owner is right; the discipline is dose, not exclusion', '**Dose & placement.** Accessories ride the same session AFTER mains. Single-joint work lives at 8-15 reps and may approach failure; rest shorter than mains (~1.5 min vs 2-4). Accessory share periodizes down as intensity rises (a cited 15-week cycle: 16 → 12 → 8 weekly sets with the squat''s share rising 25% → 75%).', 'synthesis', 'strong', NULL, NULL),
  ('doc:strength-accessories', 'Generator change (shipped with this doc)', 'Strength day templates keep mains untouched and add up to TWO supportive isolations from the assistance canon: lower/legs → hamstrings + core; upper → triceps; push → triceps + shoulders; pull → back + shoulders; full-body → core. Calves/quads/biceps/chest isolation remain hypertrophy slots. The session-cap ladder still trims accessories first when time is short, and block-level tapering toward a peak stays a future BlockProgression concern. Pinned by StrengthAccessoryTests.', 'synthesis', 'strong', NULL, NULL),
  ('doc:title-faq-themes', 'Corpus title-mined FAQ themes', 'What the field spends its breath answering, mined from question-form video titles across the 23-channel research corpus (enumerate.py export). Channel spread ranks above raw count: a question 15 channels each answer is the field''s FAQ; one channel''s obsession is not. Feeds two consumers: HelpSheet FAQ content, and what Coach should PROACTIVELY explain (advisory notes, debrief talking points).', 'synthesis', 'strong', NULL, NULL);
